Object.assign(window.ALBORZ_TECH_DATA,{"5":{"title":"آداب مدیریت نشست","subtitle":"نوبت‌دهی، مدیریت زمان و مشارکت واقعی در جلسه رسمی","icon":"🗓️","photo":"welcome","duration":"۱۵ دقیقه","situation":"نشست تمدید بیمه‌های گروهی یک شرکت آغاز شده است. مدیر منابع انسانی مشتری پی‌درپی حرف کارشناس بیمه را قطع می‌کند؛ مدیر مالی پرسش‌های تازه مطرح می‌کند و تلفن یکی از همراهان چند بار زنگ می‌خورد. جلسه فقط ۳۰ دقیقه زمان دارد.","opening":"چگونه بدون تحقیر هیچ‌کس، نظم، نوبت و نتیجه جلسه را بازمی‌گردانید؟","stakes":"توازن مشارکت، احترام به زمان، کیفیت تصمیم و مدیریت اختلاف","roles":{"a":"رئیس شعبه و گرداننده نشست هستید. باید بحث را نتیجه‌محور نگه دارید، اما نمی‌توانید طرفین را با تهدید یا دستور تند ساکت کنید.","b":"مدیر منابع انسانی شرکت هستید؛ نگران تمدید پوشش کارکنانید و حرف کارشناس را قطع می‌کنید چون تصور دارید وقت تلف می‌شود. اگر هدف و زمان‌بندی روشن شود همکاری می‌کنید."},"principles":[["توافق بر هدف و زمان","در آغاز نتیجه مطلوب، زمان و ترتیب بحث را با حاضران توافق کنید.","«۳۰ دقیقه فرصت داریم؛ ابتدا نیازها، سپس پیشنهادها و در آخر تصمیم‌های بعدی.»","«بفرمایید هرکس هر موضوعی دارد مطرح کند.»","جلسه بدون مقصد مشترک به گفت‌وگوی پراکنده تبدیل می‌شود.","نمایش دستور جلسه در یک نگاه و زمان‌سنج متعادل"],["نوبت‌دهی محترمانه","به‌جای خاموش کردن افراد، نوبت مشخص برای مشارکت ایجاد کنید.","«نظر شما را ثبت کردم؛ اجازه بدهید کارشناس پاسخ این بخش را کامل کند.»","«لطفاً وسط حرف نپرید، این رفتار شما غیرحرفه‌ای است.»","تمرکز بر فرآیند گفتگو، نه سرزنش شخصیت، تنش را کم می‌کند.","نگاه فراگیر، اشاره دعوت‌کننده، لحن قاطع"],["ثبت موضوعات خارج از دستور","موضوع مهم اما خارج از زمان را در فهرست پیگیری ثبت کنید.","«این موضوع مهم است؛ در بخش پیگیری ثبت می‌کنیم تا از هدف اصلی دور نشویم.»","«این سؤال به جلسه ما ربطی ندارد.»","Parked Topics باید مالک و زمان برگشت داشته باشند، نه فراموش شوند.","نمایش فهرست کوتاه موضوعات تعویق‌یافته"],["نظم ابزارهای دیجیتال","در جلسه رسمی توجه را از اعلان‌ها و تماس‌های غیرضروری محافظت کنید.","«اگر موافقید تلفن‌ها در حالت بی‌صدا باشند تا گفتگو پیوسته بماند.»","«همه تلفن‌ها را خاموش کنند؛ دستور من است!»","درخواست متقابل و متناسب از فرمان تحقیرکننده اثربخش‌تر است.","عدم نگاه مکرر به موبایل"],["جمع‌بندی تصمیم و عدم‌قطعیت","پایان نشست را به تصمیم‌های روشن و موارد نیازمند بررسی اختصاص دهید.","«دو موضوع توافق شد و یک مورد نیازمند تأیید ثبت شد.»","«فکر می‌کنم همه چیز مشخص است؛ جلسه تمام.»","تفاوت تصمیم مصوب و موضوع باز باید آشکار باشد.","بازگویی شفاف با مکث و تأیید جمع"]],"quiz":[{"q":"وقتی مدیر مشتری مکرر حرف کارشناس را قطع می‌کند، بهترین مداخله چیست؟","options":["با لحنی تند تذکر بدهم.","نظر او را تأیید، نوبت کارشناس را تکمیل و سپس پرسش او را باز کنم.","از کارشناس بخواهم صحبت نکند."],"correct":1,"why":"مدیریت نوبت باید هم به مشارکت و هم به کیفیت پاسخ تخصصی کمک کند.","ask":"مداخله ۱۵ ثانیه‌ای را با وب‌کم اجرا کنید."},{"q":"سؤالی مرتبط اما خارج از دستور جلسه مطرح شده است؛ چه می‌کنید؟","options":["بی‌اعتنا ادامه می‌دهم.","بحث را رها می‌کنم و آن موضوع را مفصل باز می‌کنم.","موضوع را ثبت و زمان و مسئول پیگیری تعیین می‌کنم."],"correct":2,"why":"موضوع مهم حفظ می‌شود بدون اینکه هدف اصلی و زمان‌بندی از بین برود.","ask":"تفاوت به تعویق انداختن مسئولانه و طفره رفتن را چگونه نشان می‌دهید؟"},{"q":"کدام جمله پایان جلسه دقیق‌تر است؟","options":["«دو موضوع نهایی شد؛ موضوع سوم بعد از تأیید فنی پاسخ می‌گیرد.»","«همه چیز حل شد؛ همکاری ادامه دارد.»","«نتیجه را بعداً به شما می‌گوییم.»"],"correct":0,"why":"نتیجه و عدم‌قطعیت را تفکیک می‌کند و مبنای Follow-through می‌سازد.","ask":"جمع‌بندی واقعی یک جلسه اخیر خود را در ۲۰ ثانیه بازنویسی کنید."}],"dialogue":[["الف","[به همه حاضران نگاه می‌کند] خوش آمدید. برای استفاده درست از ۳۰ دقیقه، پیشنهاد می‌کنم ابتدا نیازهای تمدید را روشن، سپس پیشنهادها را مرور و در پایان تصمیم‌های بعدی را ثبت کنیم."],["ب","ما یک مسئله فوری با پوشش کارکنان داریم؛ نمی‌خواهم جلسه صرف معرفی‌های طولانی شود."],["الف","کاملاً موافقم. اجازه بدهید با همان مسئله اصلی آغاز کنیم. مهم‌ترین تغییر موردانتظار شما در تمدید چیست؟"],["ب","افزایش سقف برخی پوشش‌ها و پاسخ سریع‌تر به تغییرات فهرست کارکنان."],["الف","این دو محور را یادداشت کردم. همکار متخصص ما تفاوت راهکارها را در چند دقیقه توضیح می‌دهد؛ سپس پرسش‌های شما را می‌شنویم."],["ب","[صحبت کارشناس را قطع می‌کند] همین راهکار قبلی هم روی کاغذ خوب بود. چرا این بار باید اعتماد کنیم؟"],["الف","[مداخله با لحن آرام] نگرانی شما درباره اجرای واقعی کاملاً مهم است. اجازه دهید همکارم توضیح این راهکار را کامل کند؛ بلافاصله درباره تجربه قبلی پرسش می‌کنیم."],["ب","باشد، اما کوتاه توضیح بدهند."],["الف","متشکرم. خواهش می‌کنم همکارمان در دو دقیقه تفاوت اصلی و محدودیت هر گزینه را بگویند."],["ب","من یک سؤال دیگر هم دارم: هزینه خدمات تکمیلی چه می‌شود؟"],["الف","موضوع هزینه مهم است؛ برای آن پنج دقیقه پایانی بخش مالی را کنار گذاشته‌ایم تا پاسخ مبتنی بر ارقام باشد."],["ب","اما مدیر مالی ما الان اینجا نشسته؛ چرا عقب بیندازیم؟"],["الف","اگر موافق باشید نخست دو انتخاب پوشش را روشن کنیم؛ آن‌وقت مقایسه هزینه‌ها دقیق‌تر خواهد بود. آیا با این ترتیب موافقید؟"],["ب","خوب است. فقط نمی‌خواهم نکته مالی فراموش شود."],["الف","ثبت شده و در جمع‌بندی بررسی می‌کنیم. اجازه بدهید دو دقیقه دیگر روی تفاوت پوشش‌ها تمرکز کنیم."],["ب","[صدای زنگ تلفن همراه یکی از حاضران] ببخشید، این تماس ممکن است کاری باشد."],["الف","بله، اگر فوری است می‌توانید خارج از اتاق پاسخ دهید. برای حفظ تمرکز جمع، پیشنهاد می‌کنم اعلان‌های غیرضروری را بی‌صدا کنیم."],["ب","درست است. حالا درباره تغییر فهرست کارکنان چه تضمینی می‌دهید؟"],["الف","فرآیند دریافت و بررسی تغییرات را با مسئول مشخص مرور می‌کنیم. برای نتیجه هر درخواست نیز باید الزامات و شرایط قرارداد رعایت شود."],["ب","ما این پاسخ را قبلاً شنیده‌ایم؛ می‌خواهم بدانم اقدام بعدی چیست."],["الف","در بخش عملیاتی، یک مسیر ارتباطی با مسئول مشخص و زمان اعلام وضعیت پیشنهاد می‌دهیم و پس از تأیید نهایی آن را ثبت می‌کنیم."],["ب","ده دقیقه بیشتر نمانده است. آیا به بحث هزینه می‌رسیم؟"],["الف","بله. دو نکته اصلی پوشش روشن شده است. اکنون پنج دقیقه برای هزینه و پنج دقیقه برای جمع‌بندی داریم."],["ب","پس لطفاً آخر جلسه مشخص کنید کدام موضوع تأیید شده و کدام هنوز باز است."],["الف","حتماً. در پایان توافق‌ها، موارد نیازمند بررسی، مسئول اقدام و موعد پاسخ را جداگانه بلندخوانی می‌کنم تا سوءتفاهمی نماند."],["ب","این ترتیب خوب است. ادامه دهیم."],["الف","متشکرم. از مدیر مالی دعوت می‌کنم نخستین پرسش مرتبط با هزینه را مطرح کنند."]],"pause":[{"at":7,"q":"مداخله رئیس شعبه چگونه نوبت را بازگرداند بدون سرزنش مهمان؟"},{"at":17,"q":"در برخورد با اعلان تلفن همراه چه مرز حرفه‌ای تعیین شد؟"},{"at":25,"q":"چگونه تصمیم قطعی از موارد باز تفکیک شد؟"}],"observe":["وضوح دستور جلسه","نوبت‌دهی بدون تحقیر","استفاده از زمان","مدیریت موضوعات خارج از دستور","کنترل حواس‌پرتی","جمع‌بندی تصمیم‌ها"],"repractice":{"trigger":"مهمان در میانه گزارش می‌گوید «این بخش وقت تلف کردن است؛ من مدیرعامل را تلفنی وارد جلسه می‌کنم.»","constraints":["اهمیت نگرانی او را به رسمیت بشناسید.","کنترل زمان و دستور جلسه را حفظ کنید.","مشارکت فرد جدید را با هدف جلسه هماهنگ کنید.","در ۶۰ ثانیه نتیجه جلسه را روشن کنید."]},"takeaways":["پیش از شروع، هدف و زمان را توافق کنید.","نوبت‌دهی محترمانه یک مهارت است.","پرسش مهم را حذف نکنید؛ مسئولانه ثبت کنید.","درخواست تمرکز دیجیتال باید متقابل باشد.","سؤال تخصصی را به فرد صلاحیت‌دار بسپارید.","هر تصمیم باید وضعیت مشخص داشته باشد.","جلسه را با صورت اقدام پایان دهید.","احترام به وقت بخشی از تشریفات است."],"sources":["Emily Post 10 Guidelines for Meetings","ارائه اصلی اسلایدهای ۸۷–۸۹ و ۱۴۸–۱۵۷"]},"6":{"title":"لحن، صدا و زبان بدن","subtitle":"هماهنگی پیام کلامی و غیرکلامی در مواجهه با بیمه‌گذار مضطرب","icon":"🎙️","photo":"voice-tone","duration":"۱۵ دقیقه","situation":"بیمه‌گذاری پس از حادثه تصادف برای راهنمایی درباره اعلام خسارت تماس تصویری برقرار می‌کند. اطلاعات او ناقص و صدایش لرزان است. رئیس شعبه باید از پشت دوربین، با لحن مناسب، توضیح روشن و زبان بدن متناسب کمک کند بدون اینکه پوشش یا مبلغ خسارت را تضمین کند.","opening":"سه جمله نخست را چگونه می‌گویید تا فرد اطلاعات درست ارائه کند و احساس کند شنیده می‌شود؟","stakes":"تنظیم هیجان، وضوح گفتار، حریم شخصی و جلوگیری از وعده بیمه‌ای نادرست","roles":{"a":"رئیس شعبه هستید؛ دوربین روشن است و باید با لحن و سرعت مناسب نیاز فرد را کشف کنید. از تشخیص پوشش یا مبلغ خسارت بدون بررسی پرهیز کنید.","b":"بیمه‌گذار مضطرب هستید؛ پس از حادثه نگران زمان اعلام و مدارک موردنیازید. اگر رئیس شعبه سریع و اصطلاحی صحبت کند، چند بار سؤال را تکرار کنید."},"principles":[["سرعت متناسب","در استرس مخاطب، سرعت و پیچیدگی گفتار را کاهش دهید.","«مرحله اول را آرام و کوتاه توضیح می‌دهم.»","«گزارش را سریع ثبت کنید و طبق بندها جلو بروید.»","سرعت گفتار باید با ظرفیت پردازش لحظه‌ای شنونده سازگار باشد.","مکث میان مراحل و جمله‌های کوتاه"],["لحن همدلانه بدون اغراق","نگرانی مخاطب را بپذیرید بدون تضمین نتیجه.","«می‌فهمم این موقعیت نگران‌کننده است؛ قدم‌به‌قدم بررسی می‌کنیم.»","«اصلاً نگران نباشید، همه خسارت پرداخت می‌شود.»","پذیرش نگرانی با تأیید نتیجه پرونده متفاوت است.","بلندی صدای متعادل و پرهیز از لحن مصنوعی"],["وضعیت بدن و نگاه","به دوربین و مخاطب توجه کنید، نه به نمایش بیش از اندازه حرکات.","«اجازه بدهید خلاصه گفته شما را بازگو کنم.»","[همزمان با توضیح، به گوشی و صفحه دیگری نگاه می‌کند]","عدم توجه بصری ممکن است احساس بی‌اعتنایی ایجاد کند؛ اما تماس چشمی باید طبیعی باشد.","قاب صورت، وضعیت نشستن، توجه به مخاطب"],["تنظیم گفت‌وگوی تصویری","نور، پس‌زمینه، کیفیت صدا و حریم خصوصی را پیش از تماس بررسی کنید.","«اگر ارتباط قطع شد از مسیر رسمی مجدد تماس می‌گیریم.»","«دوربین را هر طور هست روشن نگه دارید؛ فرقی نمی‌کند کجا باشید.»","کیفیت ارتباط تصویری بخشی از تجربه حرفه‌ای است؛ اجبار مخاطب مناسب نیست.","نور روبه‌رو، پس‌زمینه مناسب، هدست در صورت نیاز"],["بررسی فهم مخاطب","پس از هر بخش، با پرسش کوتاه فهم مشترک را بسنجید.","«برای اینکه مطمئن شوم واضح بودم، اولین قدمی که انجام می‌دهید چیست؟»","«همه چیز روشن است؟ پس خداحافظ.»","پرسش عملی بهتر از پرسش کلی بله/خیر است.","تنظیم مکث و گوش دادن کامل"]],"quiz":[{"q":"مخاطب مضطرب است و سه بار سؤال مشابه می‌پرسد؛ بهترین واکنش چیست؟","options":["همان پاسخ را با صدای بلند تکرار می‌کنم.","پاسخ را به مراحل کوتاه تقسیم و فهم او را بررسی می‌کنم.","می‌گویم توضیح من روشن بود."],"correct":1,"why":"تکرار سؤال ممکن است نشانه فشار شناختی یا ابهام باشد؛ پاسخ کوتاه و مرحله‌ای کمک می‌کند.","ask":"یک توضیح ۴۰ثانیه‌ای را به سه جمله قابل فهم تبدیل کنید."},{"q":"کدام گزینه درباره زبان بدن معتبرتر است؟","options":["نگاه نکردن به دوربین همیشه نشانه پنهان‌کاری است.","یک ژست به‌تنهایی نیت فرد را نشان نمی‌دهد و باید در بافت فهم شود.","حرکت دست دقیقاً میزان صداقت را مشخص می‌کند."],"correct":1,"why":"نشانه‌های غیرکلامی وابسته به فرد و موقعیت هستند و ابزار تشخیص قطعی صداقت نیستند.","ask":"یک ژست را در دو بافت متفاوت توضیح دهید."},{"q":"در پاسخ به سؤال «یعنی خسارتم حتماً پرداخت می‌شود؟» چه می‌گویید؟","options":["«بله؛ اصلاً نگران نباشید.»","«نمی‌دانم، به من مربوط نیست.»","«نتیجه پس از بررسی پوشش و مدارک اعلام می‌شود؛ اکنون مراحل را روشن می‌کنیم.»"],"correct":2,"why":"هم مرز تخصصی را رعایت می‌کند و هم به مخاطب مسیر عملی می‌دهد.","ask":"این جمله را با لحنی همدلانه اما قاطع اجرا کنید."}],"dialogue":[["ب","[صدای لرزان] سلام. من تصادف کرده‌ام؛ نمی‌دانم باید اول چه کاری انجام بدهم."],["الف","[با مکث کوتاه و صدای آرام] سلام. امیدوارم آسیبی ندیده باشید. قبل از هر چیز، آیا اکنون در موقعیت امنی هستید و نیاز فوری به کمک اضطراری ندارید؟"],["ب","خوشبختانه آسیب جدی نداریم، ولی خیلی نگرانم. ممکن است مهلت اعلام خسارت را از دست بدهم."],["الف","متوجه نگرانی شما هستم. اجازه بدهید اطلاعات ضروری را قدم‌به‌قدم روشن کنیم. من هم آرام توضیح می‌دهم تا چیزی جا نماند."],["ب","بگویید باید کجا بروم؟ همین حالا باید حرکت کنم؟"],["الف","قبل از مراجعه، نوع بیمه‌نامه و شرایط حادثه را بررسی می‌کنیم تا مسیر مربوط را دقیق به شما بگوییم. می‌توانید شماره بیمه‌نامه یا اطلاعات موردنیاز برای استعلام را آماده کنید؟"],["ب","شماره را دارم؛ ولی دستم می‌لرزد. شاید اشتباه بخوانم."],["الف","اشکالی ندارد. هر وقت آماده بودید، آرام می‌خوانید و من بخش‌به‌بخش تکرار می‌کنم تا از درستی اطلاعات مطمئن شویم."],["ب","[شماره را می‌خواند] خوب است؟"],["الف","[بازگویی کوتاه] من این شماره را شنیدم... لطفاً رقم آخر را یک بار دیگر بفرمایید. نمی‌خواهم اطلاعات نادرست ثبت شود."],["ب","بله درست است. حالا خسارت کامل پرداخت می‌شود؟"],["الف","نتیجه پرداخت را نمی‌توان پیش از بررسی شرایط پوشش و مدارک تعیین کرد. در این تماس می‌توانم مراحل ثبت و بررسی را با شما روشن کنم."],["ب","یعنی ممکن است پرداخت نشود؟ این حرف من را بیشتر نگران می‌کند."],["الف","درک می‌کنم. قصد ندارم شما را نگران‌تر کنم؛ می‌خواهم از وعده غیرواقعی پرهیز کنم. قدم بعدی شما مشخص است و نتیجه پس از ارزیابی رسمی اعلام می‌شود."],["ب","من دقیق متوجه نشدم اولین قدم چیست."],["الف","[سرعت را کمتر می‌کند] مرحله اول: اطلاعات حادثه را از مسیر رسمی اعلام کنید. مرحله دوم: مدارک لازم را طبق راهنمای مربوط آماده کنید. مرحله سوم: وضعیت بررسی را پیگیری کنید."],["ب","من الان فقط می‌توانم مدارک را عکس بگیرم."],["الف","برای بعضی مراحل ممکن است ارسال تصویر مجاز باشد؛ اما باید کانال رسمی و مدارک موردنیاز همان پرونده را بررسی کنیم. لطفاً اطلاعات را در پیام‌رسان غیرمجاز نفرستید."],["ب","متوجه شدم. شما به دوربین نگاه می‌کنید؛ یعنی صحبت من را واقعاً می‌شنوید؟"],["الف","[با لبخند طبیعی و توجه به مخاطب] بله، اما مهم‌تر از نگاه، این است که گفته شما را درست فهمیده باشم. نگرانی اصلی شما زمان اعلام و مدارک لازم است؛ درست است؟"],["ب","دقیقاً. من فقط می‌خواهم بدانم الان باید چه کار کنم."],["الف","پس همین دو مورد را اولویت می‌دهیم. اکنون مسیر رسمی اعلام را برای شما روشن می‌کنم و اگر امکانش باشد، راهنمای مکتوب هم در اختیارتان می‌گذاریم."],["ب","ممنون. فکر می‌کنم حالا بهتر متوجه شدم."],["الف","خوشحالم. برای اطمینان، لطفاً بفرمایید اولین قدمی که پس از تماس انجام می‌دهید چیست؟"],["ب","اطلاعات حادثه را از مسیر رسمی اعلام می‌کنم و مدارک لازم را طبق راهنمای پرونده آماده می‌کنم."],["الف","بسیار خوب. اگر در مرحله‌ای ابهام داشتید، از مسیر تماس رسمی شعبه پیگیری کنید؛ امیدوارم روند رسیدگی برایتان روشن باشد."]],"pause":[{"at":8,"q":"چرا مکث و تکرار شماره به جای عجله مناسب بود؟"},{"at":16,"q":"آیا توضیح مرحله‌ای بدون وعده پرداخت، همدلانه بود؟"},{"at":24,"q":"پرسش عملی انتهای تماس چه چیزی را می‌سنجد؟"}],"observe":["سرعت و مکث","بلندی و گرمی لحن","وضعیت بدن در دوربین","تماس چشمی متناسب","پرهیز از ذهن‌خوانی","بررسی فهم مخاطب"],"repractice":{"trigger":"مخاطب می‌گوید «فکر کنم شما اصلاً متوجه نیستید چه اتفاقی برایم افتاده» و ارتباط تصویری هم کند می‌شود.","constraints":["با لحن دفاعی واکنش ندهید.","خلاصه نگرانی او را بازگو کنید.","در صورت مشکل تصویر، راه جایگزین امن بدهید.","در ۹۰ ثانیه اولین قدم را روشن کنید."]},"takeaways":["لحن بخشی از پیام حرفه‌ای است.","در استرس، گفتار را کوتاه و مرحله‌ای کنید.","تماس چشمی طبیعی باشد، نه مصنوعی.","زبان بدن ابزار تشخیص قطعی نیت نیست.","پس‌زمینه و محرمانگی تماس اهمیت دارند.","تضمین پرداخت پیش از بررسی ندهید.","فهم را با بازگویی اقدام بسنجید.","تمرین با وب‌کم باید رفتار واقعی را نشان دهد."],"sources":["زبان بدن اسلایدهای ۱–۶۸ با بازبینی علمی","مهارت‌های ارتباطی اسلایدهای ۱–۱۲ و ۱۴–۵۲"]},"7":{"title":"کلام حرفه‌ای و قاطعانه","subtitle":"نه گفتن محترمانه، توضیح شرط قرارداد و بیان پیام دشوار","icon":"💬","photo":"professional-dress","duration":"۱۵ دقیقه","situation":"یک بیمه‌گذار سازمانی از رئیس شعبه می‌خواهد درباره خسارتی که احتمالاً مشمول استثنای پوشش است، پرداخت قطعی را تضمین کند. او می‌گوید اگر امروز تأیید نگیرید قرارداد را تمدید نمی‌کنیم و از رئیس شعبه انتظار «کمک دوستانه» دارد.","opening":"چگونه بدون اصطلاحات مبهم حقوقی، پاسخ قاطع، محترمانه و قابل دفاع می‌دهید؟","stakes":"شفافیت، حفظ روابط، مرزبندی اختیار، جلوگیری از وعده گمراه‌کننده","roles":{"a":"رئیس شعبه هستید. هنوز نظر فنی درباره پوشش قطعی نشده و اختیار تغییر مفاد قرارداد ندارید. باید مسیر بررسی را روشن کنید.","b":"مدیر خرید شرکت مشتری هستید؛ تحت فشار مدیرعامل برای دریافت پاسخ سریع قرار دارید. از رابطه چندساله به‌عنوان دلیل درخواست استثنا استفاده می‌کنید."},"principles":[["بیان مستقیم و محترمانه","پیام دشوار را بدون پیچاندن یا تحقیر روشن بیان کنید.","«در این مرحله امکان تضمین پرداخت نداریم؛ علت و مسیر بررسی را توضیح می‌دهم.»","«این پرونده اساساً به ما ربطی ندارد.»","ابهام و قطعیت ناموجه هر دو رابطه را تضعیف می‌کنند.","جملات کوتاه و افعال روشن"],["توضیح دلیل بدون دفاع‌گرایی","از ارجاع کلی به مقررات پرهیز و دلیل مرتبط را روشن کنید.","«نتیجه به مفاد بیمه‌نامه و بررسی مستندات وابسته است.»","«چون قانون است؛ دیگر سؤال نپرسید.»","توضیح دلیل باید قابل فهم و در حدود اختیار باشد.","پرهیز از واژگان تحقیرکننده و اصطلاحات اضافی"],["نه گفتن با گزینه مجاز","درخواست غیرمجاز را رد و مسیر جایگزین قانونی را معرفی کنید.","«نمی‌توانیم شرط قرارداد را نادیده بگیریم؛ امکان بررسی رسمی را پیگیری می‌کنیم.»","«برای شما استثنا قائل می‌شویم؛ خیالتان راحت.»","قاطعیت بدون مسیر اقدام ممکن است به بن‌بست ارتباطی برسد.","صدای ثابت و زبان بدن باز"],["شنیدن پشت درخواست","منافع و نگرانی مخاطب را از تاکتیک فشار جدا کنید.","«می‌خواهم بدانم فشار زمانی این تصمیم از کجاست.»","«شما فقط دنبال امتیاز ویژه هستید.»","کاوش نیاز، از برچسب‌زنی انگیزه طرف مقابل جلوگیری می‌کند.","پرسش بدون فرض پنهان"],["اعلام تعهد قابل پیگیری","فقط وعده‌ای دهید که امکان کنترل و گزارشش وجود دارد.","«تا موعد تعیین‌شده وضعیت بررسی را مکتوب اعلام می‌کنیم.»","«امروز هر طور شده مجوز را می‌گیرم.»","اعتماد از شفافیت و Follow-through شکل می‌گیرد.","تعیین مالک اقدام و مهلت معتبر"]],"quiz":[{"q":"مشتری می‌گوید «برای ما استثنا قائل شوید»؛ کدام جمله قاطعانه‌تر است؟","options":["«چون مشتری قدیمی هستید، مشکلی نیست.»","«این امکان خارج از اختیار شعبه است؛ می‌توانیم مسیر بررسی رسمی را توضیح دهیم.»","«شما همیشه درخواست غیرعادی دارید.»"],"correct":1,"why":"مرز اختیار و گزینه مجاز را هم‌زمان بیان می‌کند.","ask":"همین جمله را با دو لحن تحقیرآمیز و حرفه‌ای اجرا کنید."},{"q":"کدام جمله برای توضیح عدم قطعیت پوشش مناسب‌تر است؟","options":["«خسارت شما قطعاً مردود است.»","«فعلاً هیچ کاری نمی‌شود کرد.»","«احراز پوشش به بررسی شرایط بیمه‌نامه و مستندات نیاز دارد.»"],"correct":2,"why":"نتیجه را پیشاپیش تعیین نمی‌کند و فرآیند تصمیم را روشن می‌کند.","ask":"آن را به زبان ساده‌تر برای مخاطب غیرمتخصص بازنویسی کنید."},{"q":"در برابر تهدید به قطع همکاری چه می‌کنید؟","options":["برای حفظ مشتری قول نتیجه می‌دهم.","دغدغه تصمیم او را می‌پرسم و در چارچوب اختیار مسیر واقعی ارائه می‌کنم.","با تهدید متقابل پاسخ می‌دهم."],"correct":1,"why":"تمرکز بر دغدغه و فرآیند معتبر بهتر از واکنش هیجانی است.","ask":"یک پاسخ ۴۰ثانیه‌ای بدون عبارت «ولی» اجرا کنید."}],"dialogue":[["ب","من از شما انتظار دارم همین امروز تأیید کنید که این خسارت پرداخت می‌شود. ما مشتری قدیمی شعبه هستیم."],["الف","از سابقه همکاری شما قدردانی می‌کنیم. درباره نتیجه پرداخت، باید بر اساس مفاد بیمه‌نامه و مدارک نظر تخصصی داده شود؛ در این مرحله امکان تضمین ندارم."],["ب","این پاسخ برای ما کافی نیست؛ مدیرعامل من جواب قطعی می‌خواهد."],["الف","فشار زمانی شما را درک می‌کنم. می‌خواهم دقیق بفهمم تا چه زمانی برای تصمیم داخلی به اطلاعات نیاز دارید؟"],["ب","تا پایان امروز. وگرنه تمدید قراردادهای دیگر را هم بررسی می‌کنیم."],["الف","این موضوع برای شرکت شما مهم است. در عین حال، تصمیم فنی را نمی‌توان صرفاً بر اساس فوریت یا حجم همکاری تغییر داد."],["ب","پس سال‌ها همکاری چه ارزشی دارد؟"],["الف","ارزش همکاری در کیفیت پاسخ‌گویی، شفافیت و پیگیری جدی است؛ نه ارائه وعده‌ای که بعداً خلاف شرایط قرارداد باشد."],["ب","یکی از همکارانتان گفته بود این خسارت معمولاً پرداخت می‌شود."],["الف","ممکن است ایشان توضیح اولیه داده باشند؛ ولی هر پرونده شرایط و مستندات خاص خود را دارد. اجازه دهید گفته قبلی را هم بررسی کنیم."],["ب","یعنی می‌گویید همکار شما اشتباه کرده؟"],["الف","هنوز چنین قضاوتی ندارم. می‌گویم بیان اولیه باید از تصمیم نهایی فنی تفکیک شود و این موضوع را برای روشن شدن ثبت می‌کنم."],["ب","اگر استثنای پوشش مطرح شود، آیا می‌توانید آن را نادیده بگیرید؟"],["الف","در حدود اختیار شعبه امکان نادیده گرفتن مفاد قرارداد وجود ندارد. اگر ابهام در تفسیر باشد، مسیر بررسی رسمی آن را دنبال می‌کنیم."],["ب","من نمی‌خواهم یک پاسخ حقوقی پیچیده بشنوم."],["الف","کاملاً متوجه‌ام. به زبان ساده: باید بررسی کنیم حادثه دقیقاً زیر کدام تعهد ثبت‌شده قرارداد قرار می‌گیرد و چه مدارکی برای این تصمیم لازم است."],["ب","چطور می‌توانم به مدیرعامل گزارش بدهم وقتی هنوز نتیجه مشخص نیست؟"],["الف","می‌توانید وضعیت فعلی را دقیق گزارش دهید: پرونده در حال بررسی فنی است، مدارک مشخص‌اند و زمان پاسخ بعدی تعیین خواهد شد."],["ب","اما ایشان ممکن است بگوید بیمه البرز پاسخ نمی‌دهد."],["الف","درست است که پاسخ نهایی هنوز نداریم. پاسخ‌گویی را با اعلام شفاف مرحله پرونده، مسئول رسیدگی و موعد پیگیری نشان می‌دهیم."],["ب","چه زمانی گزارش مکتوب می‌فرستید؟"],["الف","تا پایان روز کاری، وضعیت مستندات و زمان‌بندی مرحله بعد را از مسیر رسمی به شما اعلام می‌کنیم. تاریخ پاسخ نهایی تابع تکمیل بررسی است."],["ب","می‌توانید شخصاً مسئول پیگیری باشید؟"],["الف","بله، هماهنگی پیگیری در شعبه را بر عهده می‌گیرم و در گزارش، همکار متخصص و مسیر ارجاع نیز روشن خواهد بود."],["ب","این حرف نسبت به قول قطعی منطقی‌تر است، ولی هنوز نگرانی دارم."],["الف","نگرانی شما را جدی می‌گیرم. اگر موافق باشید اکنون مدارک ناقص و سؤال‌های کلیدی را مشخص کنیم تا زمان بررسی بی‌دلیل افزایش پیدا نکند."]],"pause":[{"at":8,"q":"چرا رئیس شعبه ارزش همکاری را به معنای استثنا قائل شدن تعبیر نکرد؟"},{"at":16,"q":"کدام جمله اصطلاح فنی را به زبان ساده تبدیل کرد؟"},{"at":23,"q":"چه تعهدهایی واقعاً تحت کنترل شعبه‌اند؟"}],"observe":["بیان کوتاه و روشن","قاطعیت بدون تحقیر","تفکیک قول و اختیار","توضیح ساده مفاد","پرسشگری درباره نیاز","تعهد مشخص به پیگیری"],"repractice":{"trigger":"مشتری می‌گوید «یک جمله در ایمیل بنویسید که تمام مسئولیت خسارت با بیمه البرز است.»","constraints":["تحت فشار قول خارج از اختیار ندهید.","محدودیت درخواست را با دلیل ساده توضیح دهید.","مسیر رسمی بررسی و پاسخ را ارائه کنید.","در ۶۰ ثانیه احترام را حفظ کنید."]},"takeaways":["قاطعیت با خشونت کلامی فرق دارد.","به جای «نمی‌شود» دلیل و مسیر را بگویید.","سابقه همکاری مجوز عدول از ضوابط نیست.","به جای اصطلاحات پیچیده زبان ساده به کار برید.","پیش از نتیجه‌گیری نیاز پنهان مخاطب را بپرسید.","مفاد قرارداد و اختیار رسمی را تفکیک کنید.","تهدید به قطع همکاری را شخصی نکنید.","زمان‌بندی و مسئول پیگیری را روشن اعلام کنید."],"sources":["ارائه اصلی اسلایدهای ۵۴–۵۸ و ۱۴۸–۱۶۸","هوش هیجانی ۲، مهارت assertiveness"]}});

