Object.assign(window.ALBORZ_TECH_DATA,{"8":{"title":"مدیریت اختلالات رسمی","subtitle":"حفظ احترام و ایمنی هنگام برهم خوردن برنامه بازدید یا جلسه","icon":"🛡️","photo":"body-language","duration":"۱۵ دقیقه","situation":"در میانه بازدید رسمی مدیر ستادی، یک بیمه‌گذار سالخورده در سالن پذیرش با صدای بلند از تأخیر رسیدگی شکایت می‌کند و هم‌زمان سامانه نوبت‌دهی از کار می‌افتد. همراه مدیر ارشد می‌گوید «الان این صحنه وجهه شعبه را خراب می‌کند؛ فرد را از سالن دور کنید».","opening":"چگونه هم کرامت مشتری، هم ایمنی و هم شأن بازدید را حفظ می‌کنید؟","stakes":"ایمنی، عدالت در خدمت، حفظ شأن مشتری و مدیریت بحران کوچک عملیاتی","roles":{"a":"رئیس شعبه هستید؛ با اختلال نوبت‌دهی و اعتراض واقعی مواجهید. نباید صرفاً برای آرام‌کردن بازدید، مشتری را حذف کنید.","b":"همراه مدیر ستادی هستید؛ به تصویر عمومی شعبه حساسید و می‌خواهید مسئله سریع از دید مهمانان خارج شود. اگر راه‌حل منصفانه و فوری بشنوید همکاری می‌کنید."},"principles":[["اولویت ایمنی و کرامت","قبل از تشریفات، وضعیت جسمی، ایمنی و نیاز فوری مراجع را بررسی کنید.","«ابتدا مطمئن شویم مراجعه‌کننده در شرایط امنی است؛ بعد موضوع را رسیدگی می‌کنیم.»","«بازدید مهم است؛ ایشان را سریع از دید مهمان دور کنید.»","حضور مدیران ارشد نباید حق خدمت یا ایمنی مراجعه‌کننده را کم‌رنگ کند.","فاصله مناسب، عدم محاصره فرد معترض"],["آرام‌سازی با به‌رسمیت‌شناختن","نگرانی را بدون تأیید خودکار ادعا بشنوید.","«می‌فهمم تأخیر برای شما دشوار بوده؛ اجازه بدهید وضعیت را بررسی کنیم.»","«این همه سروصدا لازم نیست؛ ساکت باشید.»","تحقیر عمومی می‌تواند تنش را تشدید کند.","صدای کم‌تنش و دعوت محترمانه"],["تفکیک مسئولیت‌ها","هم‌زمان یک نفر برای اختلال و فردی برای رسیدگی به مشتری تعیین کنید.","«همکارم مسیر جایگزین نوبت‌دهی را فعال می‌کند؛ من پیگیری شکایت را هماهنگ می‌کنم.»","«همه کارکنان بیایند مشکل را حل کنند.»","تقسیم روشن نقش مانع توقف کامل خدمت می‌شود.","اشاره کوتاه و دستور روشن بدون آشفتگی"],["شفافیت برابر با مهمان رسمی","واقعیت را پنهان نکنید، اما جزئیات محرمانه را نیز علنی نکنید.","«اختلال ثبت شده و مسیر جایگزین عملیاتی داریم.»","«هیچ مشکلی نیست؛ این مشتری بی‌دلیل اعتراض می‌کند.»","گزارش حرفه‌ای به مسئله و اقدام اشاره می‌کند، نه تخریب شخصیت فرد.","بیان کوتاه، آرام و مسئولانه"],["بازگشت کنترل‌شده به برنامه","پس از تثبیت وضعیت، زمان و ادامه بازدید را دوباره توافق کنید.","«پس از هماهنگی خدمت‌رسانی، بازدید را از بخش دوم ادامه می‌دهیم.»","«فعلاً بازدید لغو، هیچ برنامه‌ای نداریم.»","تداوم کار نیازمند تصمیم متناسب با واقعیت و ایمنی است.","اعلام برنامه اصلاح‌شده به همه ذی‌نفعان"]],"quiz":[{"q":"در حضور مدیر ارشد، مشتری با صدای بلند اعتراض می‌کند؛ اولین اولویت چیست؟","options":["حفظ ظاهر جلسه به هر قیمت.","اطمینان از ایمنی و رسیدگی محترمانه به نیاز واقعی مشتری.","انتقال اجباری مشتری به خارج از سالن."],"correct":1,"why":"حقوق و ایمنی مراجعه‌کننده مقدم بر ظاهر تشریفاتی است.","ask":"با چه جمله‌ای به مشتری نزدیک می‌شوید که تنش بالا نرود؟"},{"q":"سامانه نوبت‌دهی هم‌زمان مختل می‌شود. پاسخ مدیریتی مناسب چیست؟","options":["همه را به یک مشکل اختصاص می‌دهم.","تقسیم مسئولیت و اجرای روش جایگزین مجاز.","می‌گویم سیستم خراب است؛ منتظر بمانید."],"correct":1,"why":"عملکرد موازی و مسئول روشن از آشفتگی جلوگیری می‌کند.","ask":"یک دستور ۱۵ثانیه‌ای بدون سرزنش کارکنان بدهید."},{"q":"همراه مدیر ستادی می‌خواهد «فرد را از دید مهمان دور کنید». چه پاسخى مناسب‌تر است؟","options":["با احترام اعلام می‌کنم رسیدگی به اعتراض در اولویت است و مکان آرام فقط با رضایت فرد پیشنهاد می‌شود.","سریع دستور می‌دهم شخص را از سالن بیرون کنند.","مهمان را بابت نگرانی‌اش سرزنش می‌کنم."],"correct":0,"why":"شفافیت، حق انتخاب و احترام به مشتری را هم‌زمان حفظ می‌کند.","ask":"«نه» حرفه‌ای در برابر فشار سلسله‌مراتبی را اجرا کنید."}],"dialogue":[["ب","[با صدای آهسته اما مضطرب] مدیر ستادی همین‌جا هستند. این مشتری چرا جلوی همه اعتراض می‌کند؟"],["الف","[لحن آرام] اعتراض ایشان را می‌شنوم. ابتدا وضعیت ایمنی و نیاز فوری‌شان را بررسی می‌کنیم تا خدمت‌رسانی متوقف نشود."],["ب","بهتر نیست از سالن بیرونشان ببرید؟ فضای بازدید را خراب کرده‌اند."],["الف","می‌توانیم فضای آرام‌تری برای گفت‌وگو پیشنهاد کنیم، اما بدون اجبار و بدون نادیده گرفتن حق رسیدگی به درخواست ایشان."],["ب","الان همه نگاه می‌کنند. مدیر ارشد درباره نظم شعبه چه فکر می‌کنند؟"],["الف","مسئولیت مدیریت این شرایط با من است. یک همکار برای رفع مشکل نوبت‌دهی اقدام می‌کند و من مسیر رسیدگی به مراجعه‌کننده را هماهنگ می‌کنم."],["ب","سامانه واقعاً از کار افتاده؟"],["الف","بله، اختلال ثبت شده است. روش جایگزین مجاز را فعال می‌کنیم تا نوبت‌ها به‌صورت منصفانه مدیریت شوند."],["ب","اگر مراجعان بیشتری اعتراض کنند چه؟"],["الف","به همه مراجعه‌کنندگان اطلاع کوتاه و روشن می‌دهیم که اختلال چیست، چه کاری انجام می‌شود و چگونه نوبت‌ها پیگیری خواهند شد."],["ب","اما ایشان می‌گویند یک ماه است منتظرند. می‌شود همین حالا پرونده را تمام کنید؟"],["الف","بدون بررسی نمی‌توانم نتیجه‌ای بدهم. اما می‌توانم مسئول رسیدگی و موعد اعلام وضعیت را مشخص کنم."],["ب","می‌خواهید در حضور مدیر ستادی مشکلات شعبه را علنی کنید؟"],["الف","مشکل عملیاتی را پنهان نمی‌کنیم؛ درباره پرونده فردی هم جزئیات محرمانه نمی‌گوییم. گزارش کلی و اقدام اصلاحی را ارائه می‌دهیم."],["ب","چه کسی با خود مشتری صحبت می‌کند؟"],["الف","من ابتدا نگرانی او را می‌شنوم و در صورت رضایتشان، همکار مسئول پرونده جزئیات را در فضای خصوصی بررسی می‌کند."],["ب","اگر نپذیرفتند به اتاق دیگری بروند؟"],["الف","در همان فضای مناسب با رعایت حریم و ایمنی گفت‌وگو را ادامه می‌دهیم. جابه‌جایی فقط یک پیشنهاد است، نه شرط دریافت خدمت."],["ب","پس برنامه بازدید چه می‌شود؟"],["الف","پس از تثبیت وضعیت، با مهمان رسمی زمان ادامه را هماهنگ می‌کنم. فعلاً تیم بازدید می‌تواند گزارش تجمیعی از بخش بعدی را دریافت کند."],["ب","این تأخیر ممکن است بازدید را طولانی کند."],["الف","حق با شماست؛ زمان جدید را روشن می‌کنیم. ترجیح می‌دهم به‌جای پنهان‌کاری، نشان دهیم اختلال را چگونه مسئولانه مدیریت می‌کنیم."],["ب","اگر مدیر ستادی مستقیم سؤال کند علت چه بود؟"],["الف","آنچه تأیید شده را گزارش می‌دهم: اختلال سامانه، اقدام جایگزین، مسئول رفع مشکل و زمان گزارش تکمیلی. درباره علت ریشه‌ای تا بررسی کامل حدس نمی‌زنم."],["ب","خوب، به نظرم برنامه عملی دارید. بعداً یک گزارش کوتاه هم بدهید."],["الف","حتماً. پس از رسیدگی، گزارش بی‌نام و تجمیعی از زمان اختلال، اقدام‌ها و پیگیری‌های پیشگیرانه آماده می‌کنیم."]],"pause":[{"at":6,"q":"چرا دور کردن اجباری مشتری راه‌حل تشریفاتی قابل دفاع نیست؟"},{"at":14,"q":"اطلاع‌رسانی به مدیر ارشد چگونه با محرمانگی جمع شد؟"},{"at":22,"q":"چه چیزی نشان می‌دهد رئیس شعبه برنامه را از دست نداده است؟"}],"observe":["اولویت ایمنی","احترام به مراجع معترض","تفویض مسئولیت","مرزبندی در برابر فشار","حفظ محرمانگی","بازتنظیم زمان و تعهد"],"repractice":{"trigger":"مدیر ستادی شخصاً می‌گوید «همین الان بازدید را ادامه بدهید؛ بقیه مسائل بعداً». در همان لحظه مشتری درخواست کمک فوری می‌کند.","constraints":["نیاز فوری و ایمنی را ارزیابی کنید.","بدون تقابل شخصی با مدیر، اولویت‌ها را روشن کنید.","تفویض مشخص انجام دهید.","برای بازدید برنامه جایگزین کوتاه پیشنهاد کنید."]},"takeaways":["تشریفات هرگز جایگزین کرامت و ایمنی نیست.","اعتراض عمومی را با تحقیر پاسخ ندهید.","فضای آرام فقط پیشنهاد محترمانه است.","در اختلال، نقش‌ها را هم‌زمان تفکیک کنید.","واقعیت را پنهان نکنید؛ اطلاعات محرمانه را هم افشا نکنید.","برای مدیران ارشد، گزارش کوتاه و مستند بدهید.","علت تأییدنشده را قطعی اعلام نکنید.","پس از اختلال، برنامه را مجدداً توافق و پیگیری کنید."],"sources":["هنر ارتباط با افراد دشوار ۲۳–۲۶","ISO 10002:2018: پاسخ‌گویی و محرمانگی"]},"9":{"title":"شناخت تفاوت ذی‌نفعان","subtitle":"تطبیق پیام و شیوه تعامل بدون تبعیض یا رفتار ترجیحی ناموجه","icon":"🧭","photo":"welcome","duration":"۱۵ دقیقه","situation":"در یک نشست هماهنگی، نماینده فروش ناراضی از زمان پاسخ شعبه، مدیر مالی یک مشتری حقوقی و کارشناس شعبه حضور دارند. نماینده می‌خواهد موضوع را تلفنی و سریع حل کند، مدیر مالی سند مکتوب می‌خواهد و کارشناس درباره محدودیت فنی هشدار می‌دهد.","opening":"چگونه با سه انتظار متفاوت گفت‌وگو می‌کنید، بدون اینکه به یکی امتیاز ناعادلانه دهید؟","stakes":"عدالت خدمت، تطبیق سبک پیام، احترام به تخصص و هماهنگی تعهدها","roles":{"a":"رئیس شعبه هستید و باید نیاز و محدودیت هر سه گروه را روشن کنید. در تصمیم‌های بیمه‌ای ضوابط یکسان و اطلاعات محرمانه رعایت شوند.","b":"نماینده فروش هستید؛ از تأخیر در پاسخ به مشتری ناراحتید و تصور دارید شعبه فروش شما را جدی نمی‌گیرد. اگر مسیر روشن و قابل پیگیری بگیرید، همکاری می‌کنید."},"principles":[["نقشه ذی‌نفعان","قبل از پاسخ، هدف و دغدغه هر مخاطب را جداگانه روشن کنید.","«برای شما زمان پاسخ، برای مدیر مالی مستندات و برای کارشناس دقت فنی اولویت است.»","«همه یک چیز می‌خواهید؛ پس یک جواب کافی است.»","نیازهای متفاوت لزوماً به تعارض منافع تبدیل نمی‌شوند.","بازتاب منصفانه دیدگاه‌ها"],["تطبیق کانال ارتباط","شکل گزارش را متناسب با نیاز و قواعد محرمانگی انتخاب کنید.","«گزارش رسمی مکتوب می‌دهیم؛ هماهنگی تلفنی را نیز در چارچوب مجاز انجام می‌دهیم.»","«همه چیز را در پیام‌رسان شخصی ارسال می‌کنیم.»","سرعت و مستندسازی باید همراه با امنیت داده باشد.","شفافیت کانال و گیرندگان مجاز"],["برابری در احترام","با هر فرد محترمانه رفتار کنید، حتی اگر جایگاه و اختیار متفاوت است.","«نظر هر سه نفر را برای تصمیم دقیق لازم داریم.»","«نظر نماینده اهمیتی ندارد؛ مدیر مالی مهم‌تر است.»","تفاوت جایگاه نباید به کاهش شأن انسانی منجر شود.","نوبت مشارکت و خطاب برابر"],["مدیریت ترجیح غیرمجاز","پاسخ‌گویی به مشتری مهم نباید به دورزدن ضوابط خدمت تبدیل شود.","«فوریت را بررسی می‌کنیم، اما ترتیب رسیدگی باید با ضوابط منطبق باشد.»","«چون مشتری شما بزرگ است، پرونده‌های دیگر را کنار می‌گذاریم.»","تطبیق خدمت با تبعیض ناموجه متفاوت است.","لحن ثابت هنگام تعیین مرز"],["گفت‌وگوی مشترک نتیجه‌محور","در پایان، نقطه اشتراک منافع و وظیفه هر فرد را روشن کنید.","«همه به پاسخ دقیق در موعد مشخص نیاز داریم؛ نقش هر واحد را تعیین کنیم.»","«هر کس موضوع خودش را جداگانه پیگیری کند.»","درک مشترک از نتیجه، همکاری بین نقش‌ها را تسهیل می‌کند.","جمع‌بندی قابل فهم برای همه"]],"quiz":[{"q":"سه ذی‌نفع نیازهای متفاوت دارند. اولین اقدام چیست؟","options":["یک پاسخ کلی برای همه اعلام می‌کنم.","هدف، نقش و نیاز هر طرف را تفکیک و بازگو می‌کنم.","فقط نظر مقام ارشد را می‌پرسم."],"correct":1,"why":"تفکیک نیاز مانع فرض غلط درباره خواسته یکسان همه می‌شود.","ask":"در ۴۵ ثانیه نیاز هر سه نقش سناریو را بیان کنید."},{"q":"نماینده از ارسال پاسخ در پیام‌رسان شخصی استقبال می‌کند اما مدیر مالی گزارش رسمی می‌خواهد. چه می‌کنید؟","options":["اطلاعات حساس را فوری در پیام‌رسان می‌فرستم.","گزارش را از کانال رسمی ارسال و هماهنگی تکمیلی را در مسیر مجاز انجام می‌دهم.","هیچ پاسخی نمی‌دهم تا همه بر یک کانال توافق کنند."],"correct":1,"why":"سرعت، مستندسازی و محرمانگی باید هم‌زمان رعایت شوند.","ask":"چگونه محدودیت کانال را بدون ناراحت کردن نماینده توضیح می‌دهید؟"},{"q":"نماینده درخواست اولویت رسیدگی فقط به دلیل حجم فروش دارد. پاسخ مناسب چیست؟","options":["همه پرونده‌های دیگر را متوقف می‌کنم.","او را به سوءاستفاده متهم می‌کنم.","فوریت واقعی را با معیارهای مصوب می‌سنجم و زمان پاسخ روشن می‌دهم."],"correct":2,"why":"ملاحظه کسب‌وکار مهم است اما معیار خدمت باید قابل دفاع بماند.","ask":"یک مرزبندی محترمانه در برابر فشار فروش اجرا کنید."}],"dialogue":[["ب","[با لحن ناراضی] ما هر روز برای پرونده مشتری تماس می‌گیریم، اما هنوز پاسخ مشخصی نمی‌گیریم. این‌طور فروش ما آسیب می‌بیند."],["الف","متوجه‌ام که زمان پاسخ برای شما و رابطه با مشتری حیاتی است. اجازه دهید دقیق روشن کنیم کدام بخش درخواست بدون پاسخ مانده است."],["ب","الحاقیه‌ای که مدیر مالی شرکت منتظر آن است. ایشان هم اینجا هستند."],["الف","خوب است که هر دو حضور دارید. از مدیر مالی می‌خواهیم بفرمایند برای تصمیم شرکت چه اطلاعاتی باید مکتوب دریافت شود."],["ب","ایشان می‌گویند گزارش رسمی می‌خواهند؛ ولی من برای هماهنگی سریع یک تماس کوتاه لازم دارم."],["الف","این دو نیاز قابل جمع‌اند: گزارش رسمی از مسیر مجاز و اطلاع‌رسانی وضعیت به نماینده از کانال تأییدشده."],["ب","چرا پاسخ اولیه را همین حالا در پیام‌رسان شخصی نفرستیم؟"],["الف","به دلیل اطلاعات قراردادی و محرمانگی، باید از کانال مجاز استفاده کنیم. می‌توانیم فوراً دریافت درخواست و مرحله رسیدگی را از مسیر رسمی تأیید کنیم."],["ب","اما کارشناس شعبه می‌گوید هنوز مستندات کافی نداریم."],["الف","از همکار متخصص می‌خواهم دقیقاً دو مورد ناقص را نام ببرد؛ هدف این است که به‌جای پاسخ مبهم، مسیر تکمیل را روشن کنیم."],["ب","اگر مدارک ناقص است چرا زودتر نگفتید؟"],["الف","این پرسش مهم است. زمان اطلاع‌رسانی قبلی را بررسی می‌کنیم و نقص فرآیند را بدون نسبت دادن تقصیر پیشاپیش اصلاح می‌کنیم."],["ب","مشتری ما مهم است. انتظار دارم پرونده او در اولویت مطلق قرار بگیرد."],["الف","اهمیت همکاری را درک می‌کنم. اولویت رسیدگی را بر اساس فوریت واقعی و ضوابط مصوب می‌سنجیم؛ نمی‌توانیم پرونده‌های دیگر را بدون مبنا کنار بگذاریم."],["ب","این حرف از نظر مشتری شبیه پاسخ منفی است."],["الف","بهتر است در کنار توضیح ضوابط، یک زمان روشن برای مرحله بعد بدهیم تا مشتری احساس نکند رها شده است."],["ب","مدیر مالی می‌خواهد بداند مسئول هر اقدام چه کسی است."],["الف","مسئول تکمیل مدارک از سمت شرکت تعیین می‌شود؛ همکار فنی پرونده را بررسی می‌کند و من هماهنگی اعلام وضعیت را پیگیری می‌کنم."],["ب","من کجای این فرآیند هستم؟"],["الف","شما حلقه هماهنگی با مشتری هستید و می‌توانید مطمئن شوید اطلاعات لازم کامل و از مسیر رسمی ارسال می‌شود."],["ب","پس من هم باید زمان مشخصی برای اطلاع به مشتری داشته باشم."],["الف","بله، زمان پاسخ مرحله‌ای را در جمع‌بندی می‌نویسیم و شما و مدیر مالی را از کانال‌های مجاز و با سطح دسترسی مناسب مطلع می‌کنیم."],["ب","اگر تأخیر دوباره تکرار شد چه؟"],["الف","در آن صورت با شناسه پیگیری مشخص، مسئله را ارجاع می‌دهیم و وضعیت ارجاع را شفاف اعلام می‌کنیم؛ نیازی به تماس‌های تکراری بدون نتیجه نخواهد بود."],["ب","این تقسیم نقش روشن‌تر است. حالا می‌توانم دقیق به مشتری گزارش بدهم."],["الف","خوشحالم. اجازه دهید هر سه توافق را کوتاه مرور کنیم و اگر کسی برداشت متفاوتی دارد همین حالا اصلاح کنیم."]],"pause":[{"at":8,"q":"چگونه نیاز به سرعت و مستندسازی بدون نقض محرمانگی پاسخ داده شد؟"},{"at":16,"q":"چرا حجم فروش دلیل کافی برای تقدم ناموجه نیست؟"},{"at":23,"q":"کدام جمله، نقش نماینده را محترمانه و عملی مشخص کرد؟"}],"observe":["بازتاب نیاز چند ذی‌نفع","انتخاب کانال مجاز","توزیع نوبت محترمانه","مرزبندی اولویت‌بندی","حفظ محرمانگی","جمع‌بندی نقش‌ها"],"repractice":{"trigger":"مدیر مالی در حضور نماینده می‌گوید «از این به بعد مستقیماً فقط با رئیس شعبه کار می‌کنیم؛ نماینده را کنار بگذارید.»","constraints":["بدون تحقیر نماینده نگرانی مشتری را بشنوید.","کانال و نقش هر فرد را بر اساس قرارداد و اختیار روشن کنید.","یک راه ارتباطی قابل پیگیری پیشنهاد دهید.","از قضاوت قطعی درباره انگیزه افراد پرهیز کنید."]},"takeaways":["مخاطبان مختلف لزوماً نیاز یکسان ندارند.","پیام را متناسب کنید؛ نه اصول خدمت را.","محرمانگی وابسته به رضایت لحظه‌ای افراد نیست.","به همه نقش‌ها فرصت بیان محترمانه بدهید.","نماینده، متخصص و مشتری را مقابل هم قرار ندهید.","فوریت را بر اساس معیار قابل دفاع بررسی کنید.","مالک اقدام و گیرنده گزارش را مشخص کنید.","نتیجه مشترک را در پایان بازتاب دهید."],"sources":["ارائه اصلی اسلایدهای ۶–۱۴ و ۱۸۶–۲۱۶","مهارت‌های ارتباطی اسلایدهای ۱–۱۲"]},"10":{"title":"جمع‌بندی، بدرقه و پیگیری","subtitle":"خاتمه حرفه‌ای ملاقات با توافق روشن، مسئول اقدام و موعد واقعی","icon":"✅","photo":"welcome","duration":"۱۵ دقیقه","situation":"پس از جلسه دشوار تمدید قرارداد یک مشتری سازمانی، سه موضوع مطرح است: یکی توافق شده، دیگری منتظر نظر فنی است و سومی به مدارک مشتری نیاز دارد. مدیرعامل شرکت در آستانه خروج می‌گوید «پس همه چیز نهایی شد، درست است؟»","opening":"چگونه در ۹۰ ثانیه آخر، سوءبرداشت را اصلاح و رابطه را حرفه‌ای خاتمه می‌دهید؟","stakes":"دقت تعهدات، جلوگیری از سوءتفاهم قراردادی، بدرقه و Follow-through","roles":{"a":"رئیس شعبه هستید. فقط یک توافق قطعی است؛ دو مورد دیگر بازند. باید بدون خراب کردن فضای مثبت، وضعیت هر موضوع را شفاف اعلام کنید.","b":"مدیرعامل مشتری هستید؛ از جلسه نسبتاً راضی‌اید اما عجله دارید و فرض کرده‌اید همه موضوع‌ها نهایی‌اند. فقط اگر تفکیک محترمانه صورت گیرد می‌پذیرید برخی موضوع‌ها باز هستند."},"principles":[["جمع‌بندی تصمیم‌ها","نتیجه هر موضوع را با وضعیت دقیق، نه عبارت کلی، بازگو کنید.","«یک موضوع نهایی، دو موضوع در مرحله بررسی یا تکمیل مدارک است.»","«همه چیز تقریباً حل شده؛ خداحافظ.»","ابهام در پایان می‌تواند سوءبرداشت قراردادی ایجاد کند.","سه‌گانه قطعی، باز و نیازمند مدرک"],["مالک اقدام","برای هر قدم آینده مسئول واقعی تعیین کنید.","«بررسی فنی با واحد مربوط و هماهنگی با من است.»","«همکاران پیگیری می‌کنند.»","مالکیت مبهم باعث کارهای بدون پیگیری می‌شود.","نام نقش یا مسئول قابل شناسایی"],["موعد واقع‌بینانه","زمان پیگیری را بر مبنای توان واقعی مشخص کنید.","«وضعیت مرحله بعد را تا موعد توافق‌شده اعلام می‌کنیم.»","«امشب همه پاسخ‌ها حتماً نهایی می‌شود.»","موعد باید مربوط به فعالیت قابل کنترل باشد، نه نتیجه نامعلوم.","بیان زمان با صدای روشن"],["تأیید برداشت مشترک","قبل از بدرقه بررسی کنید مخاطب نتیجه را درست فهمیده است.","«آیا این جمع‌بندی با برداشت شما یکسان است؟»","«فکر کنم همه موافقیم؛ دیگر سؤال نباشد.»","تأیید کوتاه، جلوی برداشت متفاوت را می‌گیرد.","مکث برای پاسخ واقعی"],["بدرقه با استمرار رابطه","با تشکر و احترام، مسیر تماس بعدی را شفاف بگذارید.","«از حضورتان سپاسگزارم؛ خلاصه توافق‌ها را از مسیر رسمی ارسال می‌کنیم.»","«حالا دیگر منتظر تماس ما باشید؛ خداحافظ.»","بدرقه حرفه‌ای فراتر از تعارف است و ادامه تعهد را نشان می‌دهد.","ایستادن، خداحافظی متناسب و احترام به وقت"]],"quiz":[{"q":"مدیرعامل در خروج می‌گوید «همه چیز نهایی شد؟» ولی دو موضوع باز است. بهترین پاسخ چیست؟","options":["برای حفظ فضای خوب می‌گویم بله.","با احترام یک موضوع نهایی و دو موضوع باز را تفکیک می‌کنم.","سکوت می‌کنم تا بعداً ایمیل بفرستم."],"correct":1,"why":"پایان خوشایند نباید با تأیید برداشت نادرست همراه شود.","ask":"جمع‌بندی ۴۵ثانیه‌ای با سه وضعیت مختلف اجرا کنید."},{"q":"برای اقدام بعدی کدام عبارت بهتر است؟","options":["«همکاران دنبال می‌کنند.»","«هر وقت آماده شد خبر می‌دهیم.»","«واحد فنی بررسی می‌کند و من موعد اعلام وضعیت را هماهنگ می‌کنم.»"],"correct":2,"why":"مسئولیت‌ها و نوع تعهد روشن‌ترند.","ask":"مالک اقدام را از ضامن نتیجه تفکیک کنید."},{"q":"اگر نتیجه نهایی به تأیید مرجع دیگر نیاز دارد، چه زمانی را وعده می‌دهید؟","options":["زمان ارائه وضعیت مرحله‌ای در محدوده اختیار، نه نتیجه قطعی.","هر زمانی که مشتری درخواست کرد.","هیچ موعدی نمی‌دهیم."],"correct":0,"why":"می‌توان زمان پیگیری را تعیین کرد بدون اینکه نتیجه فنی نامعلوم را تضمین کرد.","ask":"یک جمله مسئولانه بدون اصطلاحات مبهم بگویید."}],"dialogue":[["ب","[در حال بلند شدن] خیلی ممنون. پس همه مسائل قرارداد امروز نهایی شد و می‌توانیم در شرکت اعلام کنیم؟"],["الف","[با لبخند ملایم] از حضورتان سپاسگزارم. برای اینکه گزارش شما دقیق باشد، اجازه دهید سه موضوع را در یک دقیقه تفکیک کنم."],["ب","زمان زیادی ندارم، ولی بفرمایید."],["الف","موضوع نخست، زمان‌بندی جلسه فنی، توافق و ثبت شد. موضوع دوم، تغییر شرایط پوشش، هنوز نیازمند بررسی و تأیید است."],["ب","من تصور کردم تغییر پوشش هم تصویب شده است."],["الف","خوب شد همین حالا مطرح کردید. امروز درباره مسیر بررسی آن توافق کردیم، نه درباره نتیجه قطعی تغییر پوشش."],["ب","پس موضوع سوم، مدارک مورد نیاز، چه وضعی دارد؟"],["الف","فهرست مدارک مشخص شده و لازم است از سمت شرکت تکمیل شود تا بررسی بعدی آغاز شود."],["ب","یعنی ما هم باید کاری انجام دهیم؟"],["الف","بله. نماینده مجاز شرکت مدارک را از کانال رسمی ارسال می‌کند؛ مسئول فنی ما پس از دریافت، کامل‌بودن آن را بررسی می‌کند."],["ب","من نمی‌خواهم برای هر مورد خودم تماس بگیرم."],["الف","درست است؛ هماهنگی پیگیری شعبه با من است و یک مسیر تماس مشخص برای اطلاع‌رسانی تعیین می‌کنیم."],["ب","چه زمانی خبر می‌دهید؟"],["الف","وضعیت دریافت مدارک و مرحله بررسی را در موعدی که با شما توافق می‌کنیم اعلام می‌کنیم؛ نتیجه فنی تابع تکمیل بررسی خواهد بود."],["ب","اگر تا آن تاریخ نظر فنی صادر نشد چه؟"],["الف","در همان موعد، وضعیت واقعی و علت ادامه بررسی را اعلام می‌کنیم، بدون آنکه نتیجه نامعلوم را قطعی جلوه دهیم."],["ب","بسیار خوب. آیا این موارد را مکتوب می‌کنید؟"],["الف","بله. خلاصه شامل سه وضعیت، مسئول هر اقدام و موعد پیگیری از مسیر رسمی ارسال می‌شود؛ اطلاعات محرمانه فقط برای گیرندگان مجاز خواهد بود."],["ب","می‌خواهم مدیر مالی و مسئول قراردادها هم در جریان باشند."],["الف","گیرندگان مورد تأیید را در همان جلسه مشخص می‌کنیم تا گزارش دقیقاً به افراد مرتبط برسد."],["ب","خوب است. آیا نکته دیگری مانده؟"],["الف","یک پرسش کوتاه: آیا جمع‌بندی این سه وضعیت با برداشت شما هماهنگ است یا جایی نیاز به اصلاح دارد؟"],["ب","خیر، اکنون روشن است که فقط موضوع اول قطعی شده است."],["الف","بسیار خوب. از اینکه وقت گذاشتید سپاسگزارم. گزارش اقدامات را از مسیر رسمی می‌فرستیم و پیگیری توافق‌ها ادامه دارد."],["ب","ممنون. همین شفافیت در پایان جلسه برای ما ارزشمند است."],["الف","باعث خوشحالی است. امیدوارم ادامه همکاری با نظم و پاسخ‌گویی روشن پیش برود. بدرقه‌تان می‌کنم."]],"pause":[{"at":6,"q":"چه عبارتی یک سوءبرداشت قراردادی را بدون تنش اصلاح کرد؟"},{"at":16,"q":"چرا اعلام وضعیت قابل کنترل از وعده نتیجه نهایی متفاوت است؟"},{"at":22,"q":"تأیید برداشت مشترک چه خطری را کاهش می‌دهد؟"}],"observe":["تفکیک تصمیم قطعی و باز","ذکر مالک اقدام","زمان پیگیری واقع‌بینانه","تأیید برداشت مشترک","لحن بدرقه محترمانه","محرمانگی گزارش نهایی"],"repractice":{"trigger":"مدیرعامل هنگام خروج می‌گوید «به هیئت‌مدیره قول داده‌ام امروز پوشش جدید قطعی شود؛ لطفاً چیزی در ایمیل ننویسید که خلافش باشد.»","constraints":["برداشت نادرست را بدون تحقیر اصلاح کنید.","تفاوت توافق بر بررسی و تأیید پوشش را توضیح دهید.","تعهد مکتوب دقیق و قانونی بدهید.","بدرقه محترمانه و غیرتدافعی انجام دهید."]},"takeaways":["پایان جلسه نقطه آغاز Follow-through است.","توافق قطعی را از موضوع باز جدا کنید.","در صورت سوءبرداشت، همان لحظه اصلاح کنید.","برای هر اقدام یک مالک روشن لازم است.","موعد اطلاع‌رسانی را از موعد نتیجه جدا کنید.","خلاصه مکتوب باید دقیق و محرمانه باشد.","از مخاطب تأیید برداشت مشترک بگیرید.","بدرقه حرفه‌ای با تعهد واقعی همراه است."],"sources":["Emily Post business meeting etiquette","ارائه اصلی اسلایدهای ۱۵۵–۱۵۷ و ۱۸۶–۲۱۶"]}});

