window.ALBORZ_SIMPLE_SCENARIOS=Object.assign(window.ALBORZ_SIMPLE_SCENARIOS||{},{"2":{"situation":"ساعت ۱۰ صبح است و شعبه شلوغ شده. چند بیمه‌گذار منتظرند. مدیر منطقه بدون هماهنگی وارد می‌شود، صف را می‌بیند و می‌پرسد: «چرا مردم این‌قدر معطل شده‌اند؟» یکی از همکاران می‌گوید سیستم کند بوده، ولی شما هنوز دلیل دقیق را نمی‌دانید. مشتری‌ها و کارکنان هم صدای شما را می‌شنوند. باید در همان لحظه نشان بدهید اوضاع را دنبال می‌کنید، بدون اینکه کسی را جلوی جمع مقصر کنید.","opening":"مدیر منطقه رو‌به‌روی شماست. اولین جمله‌تان چیست؟","stakes":"آرامش، پاسخ روشن و حفظ احترام کارکنان","practice":{"skill":"آرام و محکم پاسخ دادن در شلوغی","questions":["اگر علت صف را نمی‌دانید، چه می‌گویید؟","چطور از سرزنش همکار جلوی جمع جلوگیری می‌کنید؟"],"watch":"لحن آرام، نگاه مناسب و اقدام روشن"}},"3":{"situation":"مدیرعامل یک شرکت با مدیر مالی‌اش به شعبه آمده تا درباره بیمه تجهیزات کارخانه صحبت کند. مدیر منطقه و خانم احمدی، کارشناس بیمه‌های مهندسی، هم در جلسه‌اند. شما می‌خواهید افراد را معرفی کنید. مدیرعامل نام خانم احمدی را اشتباه می‌گوید و سؤال فنی را از مدیر منطقه می‌پرسد. باید هم احترام مهمان را نگه دارید، هم نقش کارشناس خودتان را درست معرفی کنید.","opening":"جلسه را با چه معرفی کوتاهی شروع می‌کنید؟","stakes":"معرفی درست نام و نقش افراد، بدون ناراحت کردن کسی","practice":{"skill":"معرفی افراد و دعوت محترمانه از متخصص","questions":["اگر نام کارشناس را اشتباه گفتند، چه می‌گویید؟","چطور کارشناس را وارد پاسخ فنی می‌کنید؟"],"watch":"نام دقیق، نگاه به همه و دعوت محترمانه"}},"4":{"situation":"قرار است یک مهمان سازمانی با معاون منطقه ساعت ۱۱ به شعبه بیاید. مهمان پنج دقیقه زود می‌رسد؛ اتاق اصلی هنوز آماده نیست و مسئول پذیرش هم پشت میز نیست. می‌گوید: «وقت زیادی نداریم، می‌شود شروع کنیم؟» یک اتاق آرام دیگر دارید. در ادامه بازدید، مهمان می‌خواهد پرونده واقعی خسارت یک مشتری را ببیند. باید بدون دستپاچگی از مهمان استقبال کنید و در عین حال اطلاعات مشتریان را محفوظ نگه دارید.","opening":"همان لحظه که مهمان وارد می‌شود، چه می‌گویید؟","stakes":"استقبال خوب، احترام به وقت مهمان و حفظ اطلاعات مشتری","practice":{"skill":"استقبال و پیشنهاد جایگزین در موقعیت غیرمنتظره","questions":["اگر اتاق آماده نبود چه راهی پیشنهاد می‌کنید؟","درخواست پرونده واقعی را چطور محترمانه رد می‌کنید؟"],"watch":"لبخند طبیعی، راهنمایی آرام و توضیح روشن"}}});
