(function(){const bank=window.ALBORZ_TECH_DATA||{};const cases=window.ALBORZ_SIMPLE_SCENARIOS||{};const quizzes=window.ALBORZ_PLAIN_QUIZZES||{};const roles={"2":["شما رئیس شعبه‌اید. صف طولانی شده و هنوز دلیل دقیق آن را نمی‌دانید. آرام و روشن پاسخ بدهید؛ همکارتان را جلوی جمع سرزنش نکنید.","شما مدیر منطقه‌اید. صف را می‌بینید و ناراحتید. از رئیس شعبه می‌پرسید چه اتفاقی افتاده و الان چه کاری می‌کند."],"3":["شما رئیس شعبه‌اید. نام و نقش مهمان‌ها و همکاران را درست معرفی کنید و سؤال فنی را به کارشناس بسپارید.","شما مدیرعامل شرکت هستید. اسم کارشناس را اشتباه می‌گویید و از مدیر منطقه جواب فنی می‌خواهید."],"4":["شما رئیس شعبه‌اید. اتاق اصلی آماده نیست، اما اتاق جایگزین دارید. پرونده واقعی مشتری را بدون مجوز نشان ندهید.","شما مهمان سازمانی هستید. وقت کمی دارید و می‌خواهید بازدید زودتر شروع شود؛ بعد درباره دیدن یک پرونده سؤال کنید."],"5":["شما رئیس شعبه و گرداننده جلسه‌اید. باید به همه نوبت بدهید و در زمان مشخص به نتیجه برسید.","شما مدیر منابع انسانی شرکت هستید. نگران پوشش کارکنانید و چند بار حرف کارشناس را قطع می‌کنید."],"6":["شما رئیس شعبه‌اید. با صدای آرام و جمله کوتاه، مراحل اعلام خسارت را برای مشتری نگران توضیح دهید.","شما بیمه‌گذارید. تصادف کرده‌اید و نگرانید. اگر سریع توضیح شنیدید، دوباره سؤال کنید."],"7":["شما رئیس شعبه‌اید. پرونده هنوز بررسی نشده. نمی‌توانید درباره نتیجه قول بدهید؛ اما باید راه بعدی را مشخص کنید.","شما مدیر خرید مشتری قدیمی هستید. عجله دارید و از رئیس شعبه می‌خواهید جواب روشن و فوری بدهد."],"8":["شما رئیس شعبه‌اید. مشتری معترض است و سامانه نوبت‌دهی مشکل دارد. محترمانه رسیدگی کنید و کارها را تقسیم کنید.","شما همراه مدیر ستادی هستید. از شلوغی سالن ناراحتید و می‌خواهید برنامه بازدید به هم نریزد."],"9":["شما رئیس شعبه‌اید. خواسته نماینده، مدیر مالی و کارشناس را جدا بشنوید و برای هر کار مسئول مشخص کنید.","شما نماینده فروش هستید. مشتری مدام پیگیری می‌کند و شما از دیر جواب گرفتن ناراحتید."],"10":["شما رئیس شعبه‌اید. فقط یکی از سه موضوع جلسه قطعی شده. با احترام نتیجه هر مورد و کار بعدی را بگویید.","شما مدیرعامل مشتری هستید. عجله دارید و فکر می‌کنید همه موارد جلسه قطعی شده‌اند."]};for(let n=2;n<=10;n++){const d=bank[n],v=cases[n],q=quizzes[n];if(!d||!v||!q||q.length!==3)throw new Error('Missing practical content: '+n);for(const k of ['situation','opening','stakes','practice'])d[k]=v[k];d.roles={a:roles[n][0],b:roles[n][1]};d.quiz=q.map(a=>({q:a[0],options:a[1],correct:a[2],why:a[3],ask:a[4]}));}window.ALBORZ_PRACTICAL_CONTENT_READY=true;})();
