(function(){const data={"2":["به انتقاد مدیر منطقه با عصبانیت جواب ندهید.","بگویید چه چیزی را می‌دانید و چه چیزی هنوز روشن نیست.","یک کار فوری و یک کار برای جلوگیری از تکرار مشکل پیشنهاد دهید.","در تمام پاسخ، صدایتان آرام بماند."],"3":["بدون بحث‌کردن، از کار همکارتان حمایت کنید.","بگویید چه کسی مسئول تصمیم است.","از کارشناس بخواهید بخش فنی را توضیح دهد.","از مهمان بخواهید توضیح کارشناس را هم بشنود."],"4":["خرابی وسیله را گردن کسی نیندازید.","یک راه مجاز دیگر برای نمایش کار پیشنهاد دهید.","اطلاعات شخصی مشتریان را نشان ندهید.","برای ادامه بازدید یک برنامه کوتاه بگویید."],"5":["نگرانی مهمان را بشنوید.","زمان جلسه و نوبت حرف‌زدن را نگه دارید.","اگر فرد تازه‌ای به جلسه اضافه شد، موضوع را کوتاه توضیح دهید.","در پایان یک نتیجه روشن بگویید."],"6":["با آرامش گوش بدهید و حالت دفاعی نگیرید.","نگرانی مشتری را با زبان خودتان تکرار کنید.","اگر تصویر مشکل داشت، یک راه ارتباطی رسمی دیگر پیشنهاد دهید.","اولین قدم را در دو جمله بگویید."],"7":["قبل از بررسی، درباره نتیجه قول ندهید.","دلیل را ساده و کوتاه بگویید.","راه بررسی و زمان خبر بعدی را مشخص کنید.","با لحن محکم ولی محترمانه پاسخ بدهید."],"8":["اول ببینید مشتری نیاز فوری دارد یا نه.","با مدیر ستادی محترمانه درباره اولویت کار صحبت کنید.","به یک همکار کار مشخصی بسپارید.","برای ادامه بازدید یک زمان مناسب پیشنهاد دهید."],"9":["نگرانی مشتری را بشنوید و نماینده را جلوی جمع کوچک نکنید.","نقش هر نفر را طبق قرارداد روشن کنید.","یک راه امن و مشخص برای خبر دادن پیشنهاد دهید.","بدون دلیل درباره نیت افراد قضاوت نکنید."],"10":["با احترام بگویید چه چیزی هنوز قطعی نیست.","تفاوت «بررسی می‌کنیم» و «تأیید شد» را بگویید.","جمع‌بندی کوتاه و درست را مکتوب بفرستید.","محترمانه خداحافظی و پیگیری کنید."]};const bank=window.ALBORZ_TECH_DATA||{};for(const id of Object.keys(data)){if(bank[id]?.repractice)bank[id].repractice.constraints=data[id];}window.ALBORZ_SIMPLE_REPRACTICE_READY=true;})();
